from typing import List

class Solution:
    def hasIncreasingSubarrays(self, nums: List[int], k: int) -> bool:
        n = len(nums)
        # We need to find if there exists an index i such that
        # the subarray nums[i...i+k-1] is strictly increasing AND
        # the subarray nums[i+k...i+2k-1] is strictly increasing.
        # The valid range for i is such that the second subarray ends before the array ends.
        # The second subarray ends at index i + 2k - 1.
        # So i + 2k - 1 < n  =>  i <= n - 2k.
        # i ranges from 0 to n - 2k.

        for i in range(n - 2*k + 1):
            # Check if the first subarray nums[i...i+k-1] is strictly increasing
            first_inc = True
            for j in range(i, i + k - 1):
                if nums[j] >= nums[j+1]:
                    first_inc = False
                    break
            if not first_inc:
                continue

            # Check if the second subarray nums[i+k...i+2k-1] is strictly increasing
            second_inc = True
            for j in range(i + k, i + 2*k - 1):
                if nums[j] >= nums[j+1]:
                    second_inc = False
                    break

            if second_inc:
                return True

        return False

