from typing import List

class Solution:
    def maxAmount(self, initialCurrency: str, pairs1: List[List[str]], rates1: List[float], pairs2: List[List[str]], rates2: List[float]) -> float:
        # Map currencies to indices
        currency_to_idx = {initialCurrency: 0}
        for start, target in pairs1 + pairs2:
            if start not in currency_to_idx:
                currency_to_idx[start] = len(currency_to_idx)
            if target not in currency_to_idx:
                currency_to_idx[target] = len(currency_to_idx)

        num_currencies = len(currency_to_idx)
        idx_map = currency_to_idx

        # Initialize distance matrices with -infinity
        INF = float('-inf')
        dist1 = [[INF] * num_currencies for _ in range(num_currencies)]
        dist2 = [[INF] * num_currencies for _ in range(num_currencies)]

        # Initialize diagonals to 0 (0 log rate = 1.0 amount)
        for i in range(num_currencies):
            dist1[i][i] = 0
            dist2[i][i] = 0

        # Function to add edges for a day's pairs and rates
        def add_edges(pairs, rates, dist_matrix):
            for i in range(len(pairs)):
                start_curr, target_curr = pairs[i]
                rate = rates[i]
                start_idx = idx_map[start_curr]
                target_idx = idx_map[target_curr]

                # Forward edge: start -> target
                if math.log(rate) > dist_matrix[start_idx][target_idx]:
                    dist_matrix[start_idx][target_idx] = math.log(rate)
                # Backward edge: target -> start
                if -math.log(rate) > dist_matrix[target_idx][start_idx]:
                    dist_matrix[target_idx][start_idx] = -math.log(rate)

        # Add edges for Day 1
        add_edges(pairs1, rates1, dist1)

        # Add edges for Day 2
        add_edges(pairs2, rates2, dist2)

        # Floyd-Warshall for Day 1
        for k in range(num_currencies):
            for i in range(num_currencies):
                for j in range(num_currencies):
                    if dist1[i][k] != INF and dist1[k][j] != INF:
                        dist1[i][j] = max(dist1[i][j], dist1[i][k] + dist1[k][j])

        # Floyd-Warshall for Day 2
        for k in range(num_currencies):
            for i in range(num_currencies):
                for j in range(num_currencies):
                    if dist2[i][k] != INF and dist2[k][j] != INF:
                        dist2[i][j] = max(dist2[i][j], dist2[i][k] + dist2[k][j])

        max_val = 0.0
        initial_idx = idx_map[initialCurrency]

        # Check all possible intermediate currencies C
        # The path is: initialCurrency -> ... -> C (Day 1) -> ... -> initialCurrency (Day 2)
        # We want to maximize dist1[initial][C] + dist2[C][initial]
        for c_idx in range(num_currencies):
            total_log = dist1[initial_idx][c_idx] + dist2[c_idx][initial_idx]
            if total_log > max_val:
                max_val = total_log

        return math.exp(max_val)
